package steam

import (
	"context"
	"errors"
	"io"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"sync/atomic"
	"testing"
	"time"
)

// sampleDemoPayload mirrors the payload inside testdata/sample.dem.bz2. It is
// regenerated by:
//
//	python3 -c "import bz2;p=b'PBDEMS2\x00'+bytes(i%251 for i in range(4096));open('internal/steam/testdata/sample.dem.bz2','wb').write(bz2.compress(p))"
func sampleDemoPayload() []byte {
	payload := make([]byte, 0, 8+4096)
	payload = append(payload, []byte("PBDEMS2\x00")...)
	for index := 0; index < 4096; index++ {
		payload = append(payload, byte(index%251))
	}
	return payload
}

func readFixture(t *testing.T) []byte {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", "sample.dem.bz2"))
	if err != nil {
		t.Fatalf("read bz2 fixture: %v", err)
	}
	return raw
}

type progressRecord struct {
	active        bool
	percent       float64
	indeterminate bool
}

func TestImportDemoContextDownloadsAndDecompresses(t *testing.T) {
	var requests int64
	var headRequests int64
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodHead:
			atomic.AddInt64(&headRequests, 1)
			w.WriteHeader(http.StatusOK)
		default:
			atomic.AddInt64(&requests, 1)
			w.Header().Set("Content-Length", "719")
			_, _ = w.Write(readFixture(t))
		}
	}))
	defer server.Close()

	cacheRoot := t.TempDir()
	var records []progressRecord
	path, err := ImportDemoContext(context.Background(), server.URL+"/730/match.dem.bz2", "3668142292599833094", cacheRoot,
		func(active bool, percent float64, indeterminate bool) {
			records = append(records, progressRecord{active: active, percent: percent, indeterminate: indeterminate})
		})
	if err != nil {
		t.Fatalf("ImportDemoContext returned error: %v", err)
	}

	wantPath := filepath.Join(cacheRoot, "3668142292599833094.dem")
	if path != wantPath {
		t.Fatalf("path = %q, want %q", path, wantPath)
	}
	got, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read imported demo: %v", err)
	}
	if len(got) != len(sampleDemoPayload()) {
		t.Fatalf("demo size = %d, want %d", len(got), len(sampleDemoPayload()))
	}
	for index, value := range sampleDemoPayload() {
		if got[index] != value {
			t.Fatalf("demo byte %d = %d, want %d", index, got[index], value)
		}
	}

	if len(records) == 0 {
		t.Fatal("no progress was emitted")
	}
	if !records[0].active {
		t.Errorf("first progress record = %+v, want active", records[0])
	}
	if records[len(records)-1].active {
		t.Errorf("last progress record = %+v, want inactive", records[len(records)-1])
	}

	// Staging directories must not survive a successful import.
	entries, err := os.ReadDir(cacheRoot)
	if err != nil {
		t.Fatalf("read cache root: %v", err)
	}
	for _, entry := range entries {
		if entry.IsDir() {
			t.Errorf("staging directory left behind: %s", entry.Name())
		}
	}
}

func TestImportDemoContextUsesCacheWithoutDownloading(t *testing.T) {
	var requests int64
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		atomic.AddInt64(&requests, 1)
		w.WriteHeader(http.StatusInternalServerError)
	}))
	defer server.Close()

	cacheRoot := t.TempDir()
	stablePath := filepath.Join(cacheRoot, "3668142292599833094.dem")
	if err := os.WriteFile(stablePath, sampleDemoPayload(), 0644); err != nil {
		t.Fatalf("seed cache: %v", err)
	}

	path, err := ImportDemoContext(context.Background(), server.URL+"/match.dem.bz2", "3668142292599833094", cacheRoot, nil)
	if err != nil {
		t.Fatalf("ImportDemoContext returned error: %v", err)
	}
	if path != stablePath {
		t.Fatalf("path = %q, want %q", path, stablePath)
	}
	if got := atomic.LoadInt64(&requests); got != 0 {
		t.Fatalf("cache hit still issued %d requests", got)
	}
}

func TestImportDemoContextReportsExpiredLink(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusNotFound)
	}))
	defer server.Close()

	_, err := ImportDemoContext(context.Background(), server.URL+"/gone.dem.bz2", "42", t.TempDir(), nil)
	if !errors.Is(err, ErrDemoLinkExpired) {
		t.Fatalf("error = %v, want ErrDemoLinkExpired", err)
	}
}

func TestImportDemoContextRejectsMissingURLAndBadMatchID(t *testing.T) {
	if _, err := ImportDemoContext(context.Background(), "   ", "42", t.TempDir(), nil); !errors.Is(err, ErrDemoLinkUnavailable) {
		t.Fatalf("error = %v, want ErrDemoLinkUnavailable", err)
	}
	if _, err := ImportDemoContext(context.Background(), "http://example.invalid/x.dem.bz2", "../evil", t.TempDir(), nil); err == nil {
		t.Fatal("ImportDemoContext accepted a non numeric match ID")
	}
}

func TestImportDemoContextHonorsCancellation(t *testing.T) {
	release := make(chan struct{})
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		<-release
		w.WriteHeader(http.StatusOK)
	}))
	defer func() {
		close(release)
		server.Close()
	}()

	ctx, cancel := context.WithCancel(context.Background())
	cacheRoot := t.TempDir()
	done := make(chan error, 1)
	go func() {
		_, err := ImportDemoContext(ctx, server.URL+"/slow.dem.bz2", "7", cacheRoot, nil)
		done <- err
	}()

	time.Sleep(100 * time.Millisecond)
	cancel()

	select {
	case err := <-done:
		if err == nil {
			t.Fatal("cancelled import returned no error")
		}
	case <-time.After(10 * time.Second):
		t.Fatal("cancelled import did not return")
	}

	entries, err := os.ReadDir(cacheRoot)
	if err != nil {
		t.Fatalf("read cache root: %v", err)
	}
	for _, entry := range entries {
		t.Errorf("cancelled import left %s behind", entry.Name())
	}
}

func TestImportDemoContextRejectsNonDemoPayload(t *testing.T) {
	// A bz2 stream that decompresses to something without a demo stamp must not
	// be committed: this is what an error page or a truncated replay looks like.
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_, _ = w.Write(readFixture(t))
	}))
	defer server.Close()

	// The fixture is valid, so corrupt it by serving HTML instead.
	htmlServer := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_, _ = io.WriteString(w, "<html>denied</html>")
	}))
	defer htmlServer.Close()

	if _, err := ImportDemoContext(context.Background(), htmlServer.URL+"/x.dem.bz2", "9", t.TempDir(), nil); err == nil {
		t.Fatal("ImportDemoContext committed a non bz2 payload")
	}
}

func TestProbeDemoURL(t *testing.T) {
	alive := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusOK)
	}))
	defer alive.Close()
	gone := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusNotFound)
	}))
	defer gone.Close()

	if !ProbeDemoURL(context.Background(), alive.URL+"/a.dem.bz2") {
		t.Error("ProbeDemoURL(alive) = false, want true")
	}
	if ProbeDemoURL(context.Background(), gone.URL+"/a.dem.bz2") {
		t.Error("ProbeDemoURL(gone) = true, want false")
	}
	if ProbeDemoURL(context.Background(), "  ") {
		t.Error("ProbeDemoURL(empty) = true, want false")
	}
}

func TestParseMatchRef(t *testing.T) {
	numeric, err := ParseMatchRef(" 3668142292599833094 ")
	if err != nil {
		t.Fatalf("ParseMatchRef(numeric) returned error: %v", err)
	}
	if numeric.MatchID != "3668142292599833094" || numeric.ShareCode != nil {
		t.Fatalf("ParseMatchRef(numeric) = %+v", numeric)
	}

	fromCode, err := ParseMatchRef("CSGO-3MD4K-ShNFS-p3t6a-dxQJH-f9hWA")
	if err != nil {
		t.Fatalf("ParseMatchRef(share code) returned error: %v", err)
	}
	if fromCode.MatchID != "3668142292599833094" || fromCode.ShareCode == nil {
		t.Fatalf("ParseMatchRef(share code) = %+v", fromCode)
	}
	if fromCode.ShareCode.ReservationID != 3668148000611369297 {
		t.Fatalf("reservation ID = %d", fromCode.ShareCode.ReservationID)
	}

	if _, err := ParseMatchRef("not a match"); err == nil {
		t.Fatal("ParseMatchRef accepted garbage")
	}
	if _, err := ParseMatchRef(""); err == nil {
		t.Fatal("ParseMatchRef accepted empty input")
	}
}

func TestProgressComponentID(t *testing.T) {
	if got := ProgressComponentID(" 3668142292599833094 "); got != "steam_import_3668142292599833094" {
		t.Fatalf("ProgressComponentID = %q", got)
	}
}
